mapper.select:
SELECT DISTINCT ON (chan.id) chan.* from ( select channels.*,count(channels.userAccessId) as subscribeNum from ( SELECT channel.*, info.last_name AS createUserLastName, info.first_name AS createUserFirstName, tags.id AS tag_id, tags.channel_id AS tag_channel_id, tags.type AS tag_type, tags.tag_text AS tag_text, ssubscribeNumUserAccess.user_id as userAccessId, subscribeNumPermission.subscribe_permission::jsonb, subscribeNumPermission.channel_permission::jsonb
,CASE WHEN ( SELECT count(1) FROM gc_user_access_permission per LEFT JOIN gc_user_access acc ON acc.id = per.user_access_id WHERE per.subscribe_permission::jsonb @> to_jsonb(channel.id::integer) and acc.user_id = #{userId} and acc.master_id=#{masterId} GROUP BY acc.user_id ) IS NULL THEN 0 ELSE 1 END AS followFlag
FROM pt_channel channel left join gc_user us on us.id = channel.create_user_id left join gc_user_info info on info.id = us.info_id left join pt_tags tags on tags.channel_id = channel.id LEFT JOIN gc_user_access_permission subscribeNumPermission ON subscribeNumPermission.subscribe_permission::jsonb @> to_jsonb(channel.id::integer) LEFT JOIN gc_user_access ssubscribeNumUserAccess on ssubscribeNumUserAccess.id = subscribeNumPermission.user_access_id WHERE level=0 AND ssubscribeNumUserAccess.master_id =#{masterId} and channel.create_user_id != #{userId} GROUP BY channel.id, ssubscribeNumUserAccess.user_id, info.last_name, info.first_name, tags.id, subscribeNumPermission.subscribe_permission::jsonb, subscribeNumPermission.channel_permission::jsonb
order by ssubscribeNumUserAccess.user_id = #{userId} desc
order by channel.create_time desc
) as channels group by channels.id, channels.channel_name, channels.channel_img_file_id, channels."desc", channels.create_user_id, channels.visible_flag, channels.category_id, channels.level, channels.fid, channels.order, channels.master_id, channels.channel_slug, channels.create_time, channels.update_time, channels.channel_avatar_file_id, channels.createuserlastname, channels.createUserFirstName, channels.tag_id, channels.tag_channel_id, channels.tag_type, channels.tag_text, channels.userAccessId, channels.subscribe_permission, channels.channel_permission, channels.followFlag order by channels.create_time desc ) as chan LEFT JOIN pt_channel_subscribe sub on chan.id = sub.channel_id and user_id = #{userId} AND sub.is_deleted = false where chan.subscribe_permission::jsonb @> to_jsonb(chan.id::integer) and chan.create_user_id != #{userId}
and chan.userAccessId = #{userId}
order by chan.id desc, sub.create_time desc,chan.create_time desc

SELECT channel.*, access.id as code_id,access.id as code_id ,access.code as team_codename,subscribeAccess.id as subscribe_code_id, subscribeAccess.code as subscribe_code_name,subscribeAccess.group_name as groupName,access.group_name as accessGroupName FROM pt_channel channel left join content_group_channel_subscription public_cgcs on public_cgcs.channel_id = channel.id AND public_cgcs.is_subscribed = false left join gc_access access on access.id = public_cgcs.content_group_id left join content_group_channel_subscription subscribe_cgcs on subscribe_cgcs.channel_id = channel.id AND public_cgcs.is_subscribed = true left join gc_access subscribeAccess on subscribeAccess.id = subscribe_cgcs.content_group_id LEFT JOIN gc_user_access_permission permission ON permission.subscribe_permission::jsonb @> to_jsonb(channel.id::integer) LEFT JOIN gc_user_access userAccess on userAccess.id = permission.user_access_id where channel.id in
#{channelId}
and userAccess.master_id = #{masterId} and userAccess.user_id = #{userId} group by channel.id,access.id,subscribeAccess.id

SELECT channel.*,us.username as channel_create_user_username,us.id as channel_create_uid, info.last_name as userInfo_lastName,info.first_name as userInfo_firstName,subscribe_us.id as subscribe_user_id,subscribe_us.username as subscribe_user_username,subscribe_info.last_name as subscribe_userInfo_lastName, subscribe_info.first_name as subscribe_userInfo_firstName,subscribe_info.avatar_file_id as subscribe_userInfo_avatar_file_id, access.id as code_id,access.id as code_id ,access.code as team_codename,subscribeAccess.id as subscribe_code_id, subscribeAccess.code as subscribe_code_name,subscribeAccess.group_name as groupName,access.group_name as accessGroupName, (SELECT count(id) FROM pt_channel_subscribe WHERE is_deleted = false AND (channel_id = sec.id OR channel_id = channel.id)) as subscribeNum FROM pt_channel channel left join gc_user us on us.id = channel.create_user_id left join gc_user_info info on info.id = us.info_id left join pt_channel sec on sec.fid = channel.id left join pt_channel_subscribe sub on sub.channel_id = channel.id AND sub.is_deleted = false left join (SELECT u.* FROM pt_channel_subscribe sub LEFT JOIN gc_user u ON u.id = sub.user_id WHERE sub.is_deleted = false ORDER BY sub.create_time desc LIMIT 6 )subscribe_us on subscribe_us.id = sub.user_id left join gc_user_info subscribe_info on subscribe_info.id = subscribe_us.info_id left join content_group_channel_subscription public_cgcs on public_cgcs.channel_id = channel.id AND public_cgcs.is_subscribed = false left join gc_access access on access.id = public_cgcs.content_group_id left join content_group_channel_subscription subscribe_cgcs on subscribe_cgcs.channel_id = channel.id AND subscribe_cgcs.is_subscribed = true left join gc_access subscribeAccess on subscribeAccess.id = subscribe_cgcs.content_group_id WHERE 1=1
and channel.id = #{channelId}
and channel.channel_slug = #{slug}
and channel.master_id = #{masterId}
GROUP BY channel.id, us.id, info.id, subscribe_us.id, subscribe_info.id, access.id, subscribeAccess.id, sec.id, subscribe_us.username order by sec.create_time ${order}

SELECT DISTINCT ON (file.id) file.*, video_content.id as video_id, u.username as channel_create_user_username, u.id as channel_create_uid, info.last_name as createUserLastName, info.first_name as createUserFirstName, info.avatar_file_id as userInfo_avatar_file_id, content.id AS ptChannelContentId FROM gc_video video_content JOIN sys_file file ON video_content.file_id = file.id right JOIN pt_channel_content content on content.content_id=video_content.id right JOIN( select channel.* from pt_channel channel LEFT JOIN pt_channel section on section.fid = channel.id where channel.id = #{sectionId}
union select section.* from pt_channel channel LEFT JOIN pt_channel section on section.fid = channel.id where section.fid = #{sectionId}
)channel on channel.id = content.channel_id left join gc_user u on u.id = file.upload_uid left join gc_user_info info on info.id = u.info_id WHERE file.id is not null
AND video_content.video_name LIKE concat('%',#{searchName},'%')
order by file.id, file.create_time ${order}
order by file.id asc, content.create_time asc

select * from pt_channel where 1=1

    and fid = (select id from pt_channel where channel_slug = #{slug} and master_id = #{masterId})


    and fid=#{channelId}


    and master_id = #{masterId}

order by create_time ${order}

select access.*, string_agg(cgcs.channel_id::text, ',') as subscribeAccessIds
from gc_access access
    LEFT JOIN gc_user_access ua on ua.access_id = access.id
    LEFT JOIN content_group_channel_subscription cgcs on cgcs.content_group_id = access.id AND cgcs.is_subscribed = true
where ua.user_id = #{userId} and ua.master_id=#{masterId}
GROUP BY access.id;

select ch.*, u.username as channel_create_user_username,u.id as channel_create_uid,info.last_name as createUserLastName, info.first_name as createUserFirstName,tags.id as tag_id,tags.channel_id as tag_channel_id,tags.type as tag_type,tags.tag_text as tag_text, string_agg(tags.tag_text, ',') as channelTags, info.avatar_file_id as userInfo_avatar_file_id from pt_channel ch left join gc_user u on u.id = ch.create_user_id left join gc_user_info info on info.id = u.info_id left join sys_file file on file.id = info.avatar_file_id left join pt_tags tags on tags.channel_id = ch.id where 1=1
and ch.id not in
#{channelId}
and ch.channel_name like concat('%',#{name},'%')
and ch.create_user_id = #{userId}
and ch.master_id = #{masterId} and ch.level = 0 group by ch.id, u.id, info.id, tags.id order by ch.create_time desc

select b.channelSlug as channel_slug, count(b.userid) as subscribeUserIds from ( select channel.id as id, channel.channel_slug as channelSlug, userAccess.user_id as userid from pt_channel channel LEFT JOIN gc_user_access_permission permission ON permission.subscribe_permission::jsonb @> to_jsonb(channel.id::integer) LEFT JOIN gc_user_access userAccess on userAccess.id = permission.user_access_id where 1=1 and channel.channel_slug in
#{slug}
and channel.master_id = #{masterId} group by channel.channel_slug,userAccess.user_id, channel.id ) as b group by b.channelSlug

select * from ( select channels.*,
count(channels.userAccessId) as subscribeNum
count( case when channels.userAccessId!=#{userId} then 1 else null end ) AS subscribeNum
from ( SELECT channel.*, info.last_name AS createUserLastName, info.first_name AS createUserFirstName, tags.id AS tag_id, tags.channel_id AS tag_channel_id, tags.type AS tag_type, tags.tag_text AS tag_text, ssubscribeNumUserAccess.user_id as userAccessId, subscribeNumPermission.subscribe_permission::jsonb AS subscribe_permission, subscribeNumPermission.channel_permission::jsonb AS channel_permission
,CASE WHEN coalesce(( SELECT count(1) FROM gc_user_access_permission per LEFT JOIN gc_user_access acc ON acc.id = per.user_access_id WHERE per.subscribe_permission::jsonb @> to_jsonb(channel.id::integer) and acc.user_id = #{userId} and acc.master_id=#{masterId} GROUP BY acc.user_id), 0 ) =0 THEN 0 ELSE 1 END AS followFlag/*区分自己订阅的还是小队默认绑定的*/
FROM pt_channel channel LEFT JOIN pt_channel_subscribe sub on channel.id = sub.channel_id AND sub.is_deleted = false left join gc_user us on us.id = channel.create_user_id left join gc_user_info info on info.id = us.info_id left join pt_tags tags on tags.channel_id = channel.id LEFT JOIN gc_user_access_permission subscribeNumPermission ON (subscribeNumPermission.subscribe_permission::jsonb || subscribeNumPermission.channel_permission::jsonb) @> to_jsonb(channel.id::integer) LEFT JOIN gc_user_access ssubscribeNumUserAccess on ssubscribeNumUserAccess.id = subscribeNumPermission.user_access_id WHERE 1 = 1 and level=0/*type为0查不是自己创建的channel，为1查询自己创建的channel*/ AND ssubscribeNumUserAccess.master_id =#{masterId}
and concat(channel.channel_name,channel.channel_slug) like concat('%',#{channelName},'%')
or (channel.create_user_id = #{userId} and channel.master_id = #{masterId})
/*公共*/
or (channel.visible_flag = 3 and channel.master_id = #{masterId} and channel.create_user_id != #{userId})
or (channel.visible_flag = 3 and channel.master_id = #{masterId} and channel.create_user_id = #{userId})
GROUP BY channel.id, ssubscribeNumUserAccess.user_id, info.last_name, info.first_name, tags.id, tags.channel_id, tags.type, tags.tag_text, subscribeNumPermission.subscribe_permission::jsonb, subscribeNumPermission.channel_permission::jsonb
order by ssubscribeNumUserAccess.user_id = #{userId} desc, channel.create_time desc
order by channel.create_time desc
) as channels GROUP BY channels.id, channels.create_time, channels.channel_name, channels.create_user_id, channels.createUserLastName, channels.createUserFirstName, channels.tag_id, channels.tag_channel_id, channels.tag_type, channels.tag_text, channels.userAccessId, channels.subscribe_permission, channels.channel_permission, channels.followFlag, channels.channel_img_file_id, channels.desc, channels.visible_flag, channels.master_id, channels.category_id, channels.level, channels.fid, channels."order", channels.channel_slug, channels.update_time, channels.channel_avatar_file_id order by channels.create_time desc ) as chan where 1=1
AND (chan.subscribe_permission::jsonb @> to_jsonb(chan.id::integer))
and chan.userAccessId = #{userId}
OR ( chan.create_user_id = #{userId} AND chan.LEVEL = 0 AND chan.master_id = #{masterId}) or (chan.visible_flag = 3 and chan.master_id = #{masterId} and chan.create_user_id = #{userId})
AND (chan.subscribe_permission::jsonb @> to_jsonb(chan.id::integer) = false OR chan.subscribe_permission is null) AND chan.channel_permission::jsonb @> to_jsonb(chan.id::integer) and chan.create_user_id != #{userId}
and chan.userAccessId = #{userId}
/*公共*/ or (chan.visible_flag = 3 and chan.master_id = #{masterId} and chan.create_user_id != #{userId})
and concat(chan.channel_name,chan.channel_slug) like concat('%',#{channelName},'%')
